/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
// css link
import { setProfile } from '../utils/APIRoutes';
import avatarArr from './images';
import { Buffer } from 'buffer';
export default function SetProfile() {
  const navigate = useNavigate();
  const [avatars, setAvatars] = useState([]);
  const [selectedProfile, setSelectedProfile] = useState(undefined);
  const profilePicture = async () => {};

  useEffect(() => {
    const data = [];
    for (let i = 0; i < avatarArr.length; i++) {
      const image = avatarArr[i];
      const buffer = new Buffer(image);
      data.push(buffer.toString('base64'));
    }
    setAvatars(data);
  }, []);

  return (
    <div id="Avatar_Component">
      <div className="title">
        <h2>Pick an image for your profile picture</h2>
      </div>
      <div className="avatars_container">
        {avatars.map((avatar, index) => {
          return (
            <div
              key={index}
              className={`avatar ${
                selectedProfile === index ? 'selected' : ''
              }`}
            >
              <img
                src={`data:image/svg+xml;base64,${avatar}`}
                alt="profilePic"
                onClick={() => setSelectedProfile(index)}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}
